_PIXMAP_CACHE: dict[tuple[str, str, int], QPixmap] = {}
_ICON_CACHE: dict[tuple[str, str, int], QIcon] = {}


def get_pixmap(name: str, color: str = "#e4e4ec", size: int = 24) -> QPixmap:
    """Retorna un QPixmap de tamaño size x size con el icono SVG coloreado."""
    cache_key = (name, color, size)
    if cache_key in _PIXMAP_CACHE:
        return _PIXMAP_CACHE[cache_key]

    raw_svg = SVGS.get(name)
    if not raw_svg:
        # Fallback a un pixmap transparente
        pix = QPixmap(size, size)
        pix.fill(Qt.GlobalColor.transparent)
        return pix

    colored_svg = raw_svg.replace("currentColor", color)
    renderer = QSvgRenderer(QByteArray(colored_svg.encode("utf-8")))

    # Render a 2x de resolución para que en pantallas HiDPI / retina se vea ultra nítido
    scale = 2
    render_size = size * scale
    pixmap = QPixmap(render_size, render_size)
    pixmap.fill(Qt.GlobalColor.transparent)

    painter = QPainter(pixmap)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
    renderer.render(painter)
    painter.end()

    # Escalar suavemente al tamaño objetivo manteniendo suavizado
    scaled = pixmap.scaled(
        size,
        size,
        Qt.AspectRatioMode.KeepAspectRatio,
        Qt.TransformationMode.SmoothTransformation,
    )
    _PIXMAP_CACHE[cache_key] = scaled
    return scaled


def get_icon(name: str, color: str = "#e4e4ec", size: int = 24) -> QIcon:
    """Retorna un QIcon listo para ser asignado a un QPushButton/QToolButton."""
    cache_key = (name, color, size)
    if cache_key in _ICON_CACHE:
        return _ICON_CACHE[cache_key]

    pix = get_pixmap(name, color, size)
    icon = QIcon(pix)
    _ICON_CACHE[cache_key] = icon
    return icon
